import axiosConfig from "../axiosConfig"

export const apiCreateSample = async ({user_id, name, strain, header, length}) => {
    try {
        const response = await axiosConfig.post('/api/sample/createsample', 
            { name, strain, header, length }, 
            { params: { user_id } }  
        );
        return response.data;
    } catch (error) {
        throw new Error(error.message);
    }
};


export const apiGetAllSamplesByUserId = async (user_id) => {
    try {
        const response = await axiosConfig.get('/api/sample/getallsamplesbyuserid', {
            params: { user_id }
        });
        return response.data;
    } catch (error) {
        throw error.message;
    }
};
